use std::collections::HashMap;impl Solution{pub fn contains_nearby_almost_duplicate(a:Vec<i32>,k:i32,t:i32)->bool{if t<0{return false}let w=t as i64+1;let id=|x:i64|if x>=0{x/w}else{(x+1)/w-1};let mut m=HashMap::new();for i in 0..a.len(){let x=a[i]as i64;let b=id(x);if m.contains_key(&b)||m.get(&(b-1)).map(|&v|(x-v).abs()<=t as i64).unwrap_or(false)||m.get(&(b+1)).map(|&v|(x-v).abs()<=t as i64).unwrap_or(false){return true}m.insert(b,x);if i>=k as usize{m.remove(&id(a[i-k as usize]as i64));}}false}}
